import { useLayoutEffect, useRef } from "react";
import { ArrowDown } from "lucide-react";
import { animate, createAnimatable, createTimeline, spring, stagger, utils } from "animejs";
import { prefersReducedMotion } from "../lib/motion";

// The paper panel starts this far down the avatar frame, so the head
// breaks out above it — a classic manga "out of panel" figure.
const PANEL_TOP = "18%";

// Where the eyes-closed patch sits inside the 1024×1536 avatar frame
// (generated by design/avatar/build_assets.py).
const BLINK_BOX = { left: "36.133%", top: "20.508%", width: "37.109%", height: "10.417%" };

export const HeroSection = () => {
    const titleRef = useRef(null);
    const nameRef = useRef(null);
    const descriptionRef = useRef(null);
    const buttonRef = useRef(null);
    const scrollRef = useRef(null);

    const panelRef = useRef(null);
    const figureRef = useRef(null);
    const linesRef = useRef(null);
    const colorRef = useRef(null);
    const blinkRef = useRef(null);

    // Layout effect so the hidden start states land before first paint —
    // otherwise the finished avatar flashes for a frame before the intro.
    useLayoutEffect(() => {
        const chars = nameRef.current.querySelectorAll(".name-char");
        const nameText = nameRef.current.querySelector("text");

        utils.set([titleRef.current, descriptionRef.current, buttonRef.current], {
            opacity: 0,
            translateY: 20,
        });
        utils.set(chars, { strokeDasharray: 500, strokeDashoffset: 500 });
        utils.set(panelRef.current, { opacity: 0, scale: 0.92 });
        utils.set(linesRef.current, { clipPath: `inset(${PANEL_TOP} 0% 100% 0%)` });
        utils.set(colorRef.current, { clipPath: "circle(0% at 52% 26%)" });

        // Text and avatar build in parallel: the name is inked while the
        // panel's line art is drawn, then colour floods out from the face.
        const tl = createTimeline({ defaults: { ease: "outQuart" } })
            .add(titleRef.current, { opacity: [0, 1], translateY: [30, 0], duration: 900 })
            .add(panelRef.current, {
                opacity: [0, 1],
                scale: [0.92, 1],
                ease: spring({ mass: 1, stiffness: 180, damping: 16 }),
            }, 0)
            .add(linesRef.current, {
                clipPath: [`inset(${PANEL_TOP} 0% 100% 0%)`, `inset(${PANEL_TOP} 0% 0% 0%)`],
                duration: 1400,
                ease: "inOutQuad",
            }, 300)
            .add(chars, {
                strokeDashoffset: [500, 0],
                duration: 1700,
                delay: stagger(60),
                ease: "inOutQuart",
            }, 400)
            .add(nameText, { fillOpacity: [0, 1], duration: 1100, ease: "outQuad" }, "-=1100")
            .add(colorRef.current, {
                clipPath: ["circle(0% at 52% 26%)", "circle(120% at 52% 26%)"],
                duration: 1500,
                ease: "inOutCubic",
            }, 1500)
            .add(linesRef.current, { opacity: [1, 0], duration: 700, ease: "outQuad" }, "-=500")
            .add(descriptionRef.current, { opacity: [0, 1], translateY: [30, 0], duration: 1100 }, 1600)
            .add(buttonRef.current, {
                opacity: [0, 1],
                scale: [0.8, 1],
                ease: spring({ mass: 1, stiffness: 150, damping: 15 }),
            }, 2100);

        // Looping and pointer-driven motion is skipped under reduced motion —
        // the global engine speed-up would turn loops into a strobe.
        const decorative = !prefersReducedMotion();
        const cleanups = [];

        if (decorative) {
            const scrollBob = animate(scrollRef.current, {
                translateY: [0, 10, 0],
                duration: 2000,
                loop: true,
                ease: "inOutQuad",
            });

            // Blink: the closed-eye patch flashes in for a beat, every few seconds
            const blink = animate(blinkRef.current, {
                opacity: [0, 1, 1, 0],
                duration: 220,
                delay: 3600,
                loop: true,
                loopDelay: 4200,
                ease: "linear",
            });
            cleanups.push(() => scrollBob.revert(), () => blink.revert());
        }

        // 2.5D depth on desktop: figure and panel drift in opposite directions
        if (decorative && window.matchMedia("(pointer: fine)").matches) {
            const figure = createAnimatable(figureRef.current, { x: 900, y: 900, ease: "out(3)" });
            const panel = createAnimatable(panelRef.current, { x: 900, y: 900, ease: "out(3)" });
            const onMouseMove = (e) => {
                const nx = (e.clientX / window.innerWidth) * 2 - 1;
                const ny = (e.clientY / window.innerHeight) * 2 - 1;
                figure.x(nx * 12);
                figure.y(ny * 8);
                panel.x(nx * -8);
                panel.y(ny * -5);
            };
            window.addEventListener("mousemove", onMouseMove, { passive: true });
            cleanups.push(
                () => window.removeEventListener("mousemove", onMouseMove),
                () => figure.revert(),
                () => panel.revert(),
            );
        }

        return () => {
            tl.revert();
            cleanups.forEach((fn) => fn());
        };
    }, []);

    return (
        <section
            id="hero"
            className="relative min-h-screen flex flex-col justify-center px-4 pt-24 pb-20 overflow-hidden"
        >
            <div className="container max-w-6xl mx-auto grid md:grid-cols-[1.15fr_1fr] items-center gap-10 md:gap-6">
                <div className="order-2 md:order-1 space-y-6 text-center md:text-left">
                    <h1 className="text-4xl md:text-6xl">
                        <span ref={titleRef} className="inline-block text-muted-foreground"> Hi, I'm</span>
                        <svg
                            ref={nameRef}
                            viewBox="0 0 560 100"
                            role="img"
                            aria-label="Amey Bhogle"
                            className="block mt-2 mx-auto md:mx-0 w-full max-w-[560px] overflow-visible"
                        >
                            <text
                                x="0"
                                y="84"
                                textLength="556"
                                lengthAdjust="spacingAndGlyphs"
                                fontSize="96"
                                className="font-display uppercase"
                                fill="var(--foreground)"
                                stroke="var(--primary)"
                                strokeWidth="2.5"
                                strokeLinejoin="round"
                                paintOrder="stroke"
                                style={{ fillOpacity: 0 }}
                            >
                                {"Amey Bhogle".split("").map((char, i) => (
                                    <tspan key={i} className="name-char">
                                        {char === " " ? " " : char}
                                    </tspan>
                                ))}
                            </text>
                        </svg>
                    </h1>

                    <p ref={descriptionRef} className="text-lg md:text-xl text-muted-foreground max-w-xl mx-auto md:mx-0 leading-relaxed">
                        Full-Stack Developer working across React, Node.js and Express, with production
                        experience building CRM modules end-to-end and a live Flutter app on the Play Store.
                        Recently shipped a RAG-based AI agent that automates real business workflows.
                    </p>

                    <div ref={buttonRef} className="pt-2">
                        <a href="#projects" className="ink-button text-lg px-8 group">
                            View My Work
                            <ArrowDown className="h-4 w-4 group-hover:translate-y-1 transition-transform" />
                        </a>
                    </div>
                </div>

                {/* Avatar: paper panel behind, figure breaking out of its top edge */}
                <div className="order-1 md:order-2 relative w-full max-w-[280px] sm:max-w-[340px] md:max-w-[440px] mx-auto aspect-[2/3]">
                    <div
                        ref={panelRef}
                        aria-hidden="true"
                        className="absolute inset-x-0 bottom-0 bg-foreground overflow-hidden"
                        style={{ top: PANEL_TOP, boxShadow: "8px 8px 0 0 var(--primary)" }}
                    >
                        <div className="halftone absolute inset-0 opacity-40" />
                    </div>

                    <div ref={figureRef} className="absolute inset-0">
                        <img
                            ref={linesRef}
                            src="/hero/avatar-lines.webp"
                            alt=""
                            aria-hidden="true"
                            width="1024"
                            height="1536"
                            className="absolute inset-0 w-full h-full select-none pointer-events-none"
                        />
                        <img
                            ref={colorRef}
                            src="/hero/avatar.webp"
                            alt="Anime-style illustration of Amey Bhogle in sunglasses and a black hoodie"
                            width="1024"
                            height="1536"
                            fetchPriority="high"
                            className="absolute inset-0 w-full h-full select-none pointer-events-none"
                        />
                        <img
                            ref={blinkRef}
                            src="/hero/avatar-blink.webp"
                            alt=""
                            aria-hidden="true"
                            className="absolute select-none pointer-events-none opacity-0"
                            style={BLINK_BOX}
                        />
                    </div>
                </div>
            </div>

            <div ref={scrollRef} className="absolute bottom-8 left-1/2 -translate-x-1/2 hidden md:flex flex-col items-center">
                <span className="text-xs uppercase tracking-widest text-muted-foreground mb-2"> Scroll </span>
                <div className="w-px h-10 bg-gradient-to-b from-primary to-transparent" />
            </div>
        </section>
    );
};
